  function inRing(lon, lat, r) {
    let inside = false;
    for (let i = 0, j = r.length - 2; i < r.length; j = i, i += 2) {
      const xi = r[i], yi = r[i + 1], xj = r[j], yj = r[j + 1];
      if ((yi > lat) !== (yj > lat) && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
    }
    return inside;
  }
  // even-odd over all rings handles holes (e.g. Lesotho inside South Africa)
  function countryAt(lon, lat) {
    for (const c of COUNTRIES) {
      let k = 0;
      for (const r of c.rings) if (inRing(lon, lat, r)) k++;
      if (k % 2) return c;
    }
    let best = null, bd = Infinity;            // nearest vertex (coastal / lake fixes)
    for (const c of COUNTRIES) for (const r of c.rings) for (let i = 0; i < r.length; i += 2) {
      const d = (r[i] - lon) ** 2 + (r[i + 1] - lat) ** 2;
      if (d < bd) { bd = d; best = c; }
    }
    return bd < 4 ? best : null;               // within ~2 degrees
  }
  /* Most common country among (up to 500) sampled points -> {a3, country, tz} */
  function lookup(lons, lats) {
    const n = lons.length, step = Math.max(1, Math.floor(n / 500)), tally = new Map();
    for (let i = 0; i < n; i += step) {
      if (!Number.isFinite(lons[i]) || !Number.isFinite(lats[i])) continue;
      const c = countryAt(lons[i], lats[i]);
      if (c) tally.set(c, (tally.get(c) || 0) + 1);
    }
    let best = null, bn = 0;
    for (const [c, k] of tally) if (k > bn) { bn = k; best = c; }
    return best ? { a3: best.a3, country: best.name, tz: TZ[best.a3] || "UTC" } : null;
  }
  const ALL_TZ = [...new Set(Object.values(TZ))].sort();
  EMT.tzlookup = { lookup, countryAt, ALL_TZ, TZ };
